import re

from django.db import migrations, models


def fill_local_seo(apps, schema_editor):
    """Pre-fill from what the site already shows: postal code/locality from the
    address, opening hours from the old hard-coded footer."""
    CompanySettings = apps.get_model('app', 'CompanySettings')
    for company in CompanySettings.objects.all():
        match = re.search(r'(\d{4}-\d{3})\s+(.+)$', company.address or '')
        if match:
            company.postal_code = match.group(1)
            company.locality = match.group(2).strip()
        company.weekday_hours = '09:00-19:00'
        company.saturday_hours = '10:00-16:00'
        company.sunday_hours = ''
        company.service_areas = '\n'.join([
            'Loures', 'Odivelas', 'Lisboa', 'Mafra', 'Vila Franca de Xira',
            'Arruda dos Vinhos', 'Sobral de Monte Agraço',
        ])
        company.save()


